(() => {
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const header=document.querySelector('#header'),menuButton=document.querySelector('.menu-toggle'),mobileNav=document.querySelector('#mobile-nav'),dropdownButton=document.querySelector('.nav-trigger'),dropdown=document.querySelector('#services-menu'),dialog=document.querySelector('#estimate-dialog');
  let lenis,previousFocus,requestText='';
  function setDropdown(open){dropdown.hidden=!open;dropdownButton.setAttribute('aria-expanded',String(open));if(open&&window.gsap&&!reduced)gsap.fromTo(dropdown,{opacity:0,y:-8},{opacity:1,y:0,duration:.3});}
  dropdownButton.addEventListener('click',()=>setDropdown(dropdown.hidden));
  document.addEventListener('click',e=>{if(!e.target.closest('.nav-dropdown'))setDropdown(false);});
  function setMenu(open){mobileNav.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.body.classList.toggle('modal-open',open);if(open)lenis?.stop();else lenis?.start();}
  menuButton.addEventListener('click',()=>setMenu(mobileNav.hidden));
  mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
  const descriptions={mow:'An even cut brings the whole yard together. Start with mowing, then build a routine around your lawn and how you use it.',edge:'Clean borders frame your lawn. Focus on the details along paths, driveways, and garden beds for a more finished appearance.',clean:'Give your outdoor space a fresh start. Share the leaves, debris, or overgrowth you want addressed and plan the work with JCP.',routine:'Keep lawn care on a schedule that works for you. Start a conversation about recurring visits and the priorities for your property.'};
  const inclusions={mow:['Lawn mowing','Care around borders and obstacles','One-time or recurring care enquiries'],edge:['Lawn and walkway boundaries','Detail work around garden beds','A tidy, more defined finish'],clean:['Leaf and yard debris enquiries','Attention to overgrown areas','Cleanup scope agreed in advance'],routine:['Recurring lawn maintenance enquiries','Priorities for your lawn and borders','Schedule confirmed directly with JCP']};
  const interests={mow:'Lawn care & mowing',edge:'Edging & finishing',clean:'Seasonal yard cleanup',routine:'Ongoing yard care'};
  function chooseService(key){document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===key;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelector('#service-description').textContent=descriptions[key];document.querySelector('#service-inclusions').replaceChildren(...inclusions[key].map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));document.querySelector('#service-estimate').dataset.interest=interests[key];window.dispatchEvent(new CustomEvent('jcp-service',{detail:key}));}
  document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>chooseService(b.dataset.view)));
  chooseService('mow');
  document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{chooseService(a.dataset.service);setDropdown(false);}));
  function openDialog(target){previousFocus=document.activeElement;target.showModal();target.setAttribute('data-lenis-prevent','');document.body.classList.add('modal-open');lenis?.stop();if(window.gsap&&!reduced)gsap.fromTo(target,{opacity:0,y:20},{opacity:1,y:0,duration:.35});}
  document.querySelectorAll('[data-estimate]').forEach(button=>button.addEventListener('click',()=>{if(!mobileNav.hidden)setMenu(false);setDropdown(false);document.querySelector('#estimate-form').hidden=false;document.querySelector('#request-ready').hidden=true;document.querySelector('#copy-status').textContent='';if(button.dataset.interest)document.querySelector('#estimate-form [name=service]').value=button.dataset.interest;openDialog(dialog);}));
  document.querySelector('#privacy-open').addEventListener('click',()=>openDialog(document.querySelector('#privacy-dialog')));
  document.querySelectorAll('dialog').forEach(modal=>{modal.querySelector('[data-close]').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');lenis?.start();previousFocus?.focus();});});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){setDropdown(false);if(!mobileNav.hidden){setMenu(false);menuButton.focus();}}if(e.key==='Tab'&&!mobileNav.hidden){const items=[menuButton,...mobileNav.querySelectorAll('a,button')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
  const form=document.querySelector('#estimate-form'),ready=document.querySelector('#request-ready');
  form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);requestText=`Hello JCP Lawn Service,\n\nI’d like to request an estimate.\n\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nEmail: ${d.get('email')}\nProperty: ${d.get('address')}\nService: ${d.get('service')}\nFrequency: ${d.get('frequency')}\nYard condition: ${d.get('condition')}\nPreferred timing: ${d.get('timing')}\n\n${d.get('details')||'Please contact me to discuss my yard.'}\n\nThank you!`;document.querySelector('#request-summary').textContent=requestText;document.querySelector('#send-email').href='mailto:juancpantoja78@gmail.com?subject='+encodeURIComponent('Lawn care estimate request — '+d.get('name'))+'&body='+encodeURIComponent(requestText);form.hidden=true;ready.hidden=false;dialog.scrollTop=0;document.querySelector('#send-email').focus();});
  document.querySelector('#edit-request').addEventListener('click',()=>{ready.hidden=true;form.hidden=false;form.elements.name.focus();});
  document.querySelector('#copy-request').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(requestText);document.querySelector('#copy-status').textContent='Copied. Paste into an email to juancpantoja78@gmail.com.';}catch{document.querySelector('#copy-status').textContent='Select and copy the request above, then email juancpantoja78@gmail.com.';}});
  document.querySelector('#lead-form').addEventListener('submit',event=>{event.preventDefault();const source=event.currentTarget;if(!source.reportValidity())return;for(const [key,value] of new FormData(source)){if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;}openDialog(dialog);form.hidden=false;ready.hidden=true;form.requestSubmit();});
  document.querySelectorAll('.faq-list details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.faq-list details').forEach(other=>{if(other!==item)other.open=false;});window.ScrollTrigger?.refresh();}));
  document.querySelector('#year').textContent=new Date().getFullYear();
  const sections=[...document.querySelectorAll('.chapter,#contact')];
  let previousChapter=-1;
  function updateScene(){header.classList.toggle('scrolled',scrollY>60);let active=0;sections.forEach((s,i)=>{if(s.getBoundingClientRect().top<innerHeight*.45)active=i;});document.querySelectorAll('.scene-pagination a').forEach((a,i)=>a.classList.toggle('active',i===active));document.body.classList.toggle('at-care',active===1);document.body.classList.toggle('at-contact',document.querySelector('#services').getBoundingClientRect().top<innerHeight*.5);const playRect=document.querySelector('#play').getBoundingClientRect();document.body.classList.toggle('at-play',playRect.top<innerHeight*.45&&playRect.bottom>innerHeight*.45);if(active!==previousChapter){previousChapter=active;window.dispatchEvent(new CustomEvent('jcp-chapter',{detail:active}));}}
  addEventListener('scroll',updateScene,{passive:true});addEventListener('resize',updateScene);addEventListener('load',updateScene);updateScene();
  if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);if(!reduced&&window.Lenis&&matchMedia('(pointer:fine)').matches){lenis=new Lenis({lerp:.075,smoothWheel:true,anchors:{offset:-20}});lenis.on('scroll',ScrollTrigger.update);gsap.ticker.add(t=>lenis.raf(t*1000));gsap.ticker.lagSmoothing(0);}if(!reduced){gsap.timeline({delay:.15}).from('.hero h1 span',{y:50,opacity:0,duration:1.4,stagger:.1,ease:'power4.out'}).from('.hero .eyebrow,.hero-description,.hero-actions,.hero-signature',{y:20,opacity:0,stagger:.1,duration:.9},.25).from('.world-tag,.scroll-story',{opacity:0,duration:1},.8);sections.slice(1,4).forEach(s=>gsap.from(s.querySelectorAll('.chapter-content'),{opacity:0,y:35,duration:1,ease:'power3.out',scrollTrigger:{trigger:s,start:'top 70%',once:true}}));}if(!reduced){gsap.utils.toArray('.section-heading,.reviews-header,.service-details-intro').forEach(item=>gsap.from(item,{y:28,opacity:0,duration:.9,scrollTrigger:{trigger:item,start:'top 90%',once:true}}));}addEventListener('load',()=>ScrollTrigger.refresh());document.fonts?.ready.then(()=>ScrollTrigger.refresh());}
})();
